### 4. Minimal Failing Deterministic Test Design

This test simulates the real xterm geometry and buffer resize behavior during tab reactivation without requiring a browser window:

```ts
import { describe, expect, it, vi } from "vitest";
import { Terminal } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";

describe("Terminal tab activation viewport geometry", () => {
  it("fails: shrinking row count during tab reactivation causes 1-row vertical scroll offset", async () => {
    const container = document.createElement("div");
    document.body.appendChild(container);

    // 1. Setup terminal instance
    const terminal = new Terminal({ rows: 24, cols: 80, lineHeight: 1.0 });
    const fitAddon = new FitAddon();
    terminal.loadAddon(fitAddon);
    terminal.open(container);

    // Mock cell dimensions (e.g. 10px width, 20px height)
    const core = (terminal as any)._core;
    core._renderService.dimensions = {
      css: {
        cell: { width: 10, height: 20 },
        canvas: { width: 800, height: 480 },
      },
    };

    // 2. Simulate shell session filling exactly 24 rows with cursor at row 23
    for (let i = 0; i < 23; i++) {
      terminal.writeln(`line ${i}`);
    }
    terminal.write("user@ferryx:~$ ");

    // Baseline: viewport is at top (ydisp = 0, ybase = 0)
    expect(terminal.buffer.active.ydisp).toBe(0);
    expect(terminal.buffer.active.ybase).toBe(0);

    // 3. Simulate Tab Deactivation -> Reactivation:
    // Container height is measured under real layout (e.g. 460px -> 23 rows)
    // Container height 460px / cell height 20px = 23 rows (1 row less than initial 24)
    Object.defineProperty(container, "parentElement", {
      value: {
        getBoundingClientRect: () => ({ width: 800, height: 460 }),
      },
      configurable: true,
    });
    vi.spyOn(window, "getComputedStyle").mockImplementation((el) => {
      if (el === container) {
        return {
          getPropertyValue: (prop: string) => (prop === "height" ? "460px" : "800px"),
        } as any;
      }
      return {
        getPropertyValue: () => "0px",
      } as any;
    });

    // 4. FitAddon resizes terminal from 24 to 23 rows on activation
    fitAddon.fit();
    expect(terminal.rows).toBe(23);

    // 5. Assertion: Viewport scroll offset must remain at ydisp == ybase (aligned to prompt)
    // In unpatched xterm buffer reflow without explicit scrollToBottom(),
    // ybase becomes 1 and ydisp becomes 1 (top line 0 is scrolled off screen).
    expect(terminal.buffer.active.ydisp).toBe(0); // FAILS: received 1
  });
});
```
